def f(g):
    h,w=len(g),len(g[0])
    o=[r[:] for r in g]
    pts=[(i,j) for i in range(h) for j in range(w) if g[i][j]==2]
    from collections import Counter
    rc=Counter(i for i,j in pts)
    line_row=max(rc,key=lambda r:rc[r]) if rc else None
    if line_row is not None and rc[line_row]>=2:
        cols=[j for i,j in pts if i==line_row]
        for j in range(min(cols),max(cols)+1):
            if o[line_row][j]==0: o[line_row][j]=3
        for i,j in pts:
            if i==line_row: continue
            step=1 if i<line_row else -1
            r=i+step
            while r!=line_row:
                if o[r][j]==0: o[r][j]=3
                r+=step
    return o
